#include <bits/stdc++.h>
using namespace std;

struct Node {
    int x, y, t;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int grid[8][8] = {};
    int vx = 0, vy = 0;
    Node start{0, 0, 0};

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            char c;
            cin >> c;

            if (c == 'S') {
                grid[i][j] = -1;
            } else {
                grid[i][j] = 0;
            }

            if (c == 'A') {
                vx = i;
                vy = j;
            } else if (c == 'M') {
                start.x = i;
                start.y = j;
            }
        }
    }

    bool visited[81][8][8] = {};
    queue<Node> q;
    q.push(start);
    visited[0][start.x][start.y] = true;

    const int dx[] = {-1, 1, 0, 0};
    const int dy[] = {0, 0, -1, 1};
    bool win = false;

    while (!q.empty()) {
        Node current = q.front();
        q.pop();

        if (current.t == 80) {
            continue;
        }

        if (current.x == vx && current.y == vy) {
            win = true;
            break;
        }

        int obstacleRow = current.x + current.t - 1;
        if (obstacleRow >= 0 && obstacleRow < 8 &&
            grid[obstacleRow][current.y] == -1) {
            continue;
        }

        int nextTime = current.t + 1;

        for (int direction = 0; direction < 4; ++direction) {
            int nx = current.x + dx[direction];
            int ny = current.y + dy[direction];

            if (nx < 0 || nx >= 8 || ny < 0 || ny >= 8) {
                continue;
            }

            if (!visited[nextTime][nx][ny]) {
                visited[nextTime][nx][ny] = true;
                q.push({nx, ny, nextTime});
            }
        }
    }

    cout << (win ? "WIN" : "LOSE");
    return 0;
}

